<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const notificationOptions = [
      { id: "notification-email", value: "email", label: "Email" },
      { id: "notification-sms", value: "sms", label: "SMS" },
      { id: "notification-push", value: "push", label: "Push Notifications" }
    ];

    function RadioOption({ id, value, label, required }) {
      return `
        <label class="choice" for="${id}">
          <input
            type="radio"
            id="${id}"
            name="notificationPreference"
            value="${value}"
            aria-invalid="false"
            ${required ? "required" : ""}
          >
          <span class="choice-text">${label}</span>
        </label>
      `;
    }

    function NotificationForm() {
      const optionsMarkup = notificationOptions
        .map((option, index) => RadioOption({ ...option, required: index === 0 }))
        .join("");

      return `
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>
                How do you prefer to receive notifications?
                <span class="required-note" id="notification-help">Required. Choose one answer.</span>
              </legend>
              <div class="choices">
                ${optionsMarkup}
              </div>
            </fieldset>
          </div>
          <button class="submit-button" type="submit">Submit</button>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

    function App() {
      return `
        <main class="page-shell" id="main-content">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Preferences</p>
            <h1 id="page-title">Notification settings</h1>
            <p class="intro">
              Select the single channel that works best for timely updates and account reminders.
            </p>
            ${NotificationForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const notificationForm = document.getElementById("notification-form");
    const notificationRadios = notificationForm.querySelectorAll("input[name='notificationPreference']");

    function setNotificationGroupInvalid(isInvalid) {
      notificationRadios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    }

    notificationForm.addEventListener("change", (event) => {
      if (event.target.matches("input[name='notificationPreference']")) {
        setNotificationGroupInvalid(false);
        document.getElementById("form-status").textContent = "";
      }
    });

    notificationForm.addEventListener("submit", (event) => {
      event.preventDefault();

      const form = event.currentTarget;
      const status = document.getElementById("form-status");
      const selected = form.elements.notificationPreference.value;

      if (!selected) {
        const firstRadio = notificationRadios[0];
        setNotificationGroupInvalid(true);
        status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
        firstRadio.focus();
        return;
      }

      setNotificationGroupInvalid(false);
      const selectedOption = notificationOptions.find((option) => option.value === selected);
      status.textContent = `Preference saved: ${selectedOption.label}.`;
    });
  </script>
</body>
