    :root {
      color-scheme: dark;
      --background: #0b1020;
      --surface: #121a2f;
      --surface-strong: #19243f;
      --text: #f7f9ff;
      --muted: #c2cbe0;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --border: #34425f;
      --focus: #fde68a;
      --shadow: #030712;
    }

    * {
      box-sizing: border-box;
    }

    html {
      min-height: 100%;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, #1e3a8a 0, transparent 32rem),
        radial-gradient(circle at bottom right, #0e7490 0, transparent 28rem),
        var(--background);
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      z-index: 10;
      padding: 0.75rem 1rem;
      color: #06111f;
      background: var(--focus);
      border-radius: 999px;
      transform: translateY(-150%);
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 0.125rem solid transparent;
      box-shadow: 0 0 0 0.25rem #06111f;
    }

    .page-shell {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 42rem);
      padding: clamp(1.25rem, 5vw, 3rem);
      background: linear-gradient(145deg, var(--surface), var(--surface-strong));
      border: 0.0625rem solid var(--border);
      border-radius: 1.5rem;
      box-shadow: 0 1.5rem 4rem var(--shadow);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 8vw, 3.5rem);
      line-height: 1.05;
    }

    .intro {
      max-width: 36rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.0625rem;
    }

    form {
      display: grid;
      gap: 1.5rem;
    }

    .form-field {
      padding: 0;
      border: 0;
    }

    fieldset {
      min-inline-size: 0;
      padding: 0;
      margin: 0;
      border: 0;
    }

    legend {
      padding: 0;
      margin-bottom: 1rem;
      color: var(--text);
      font-size: 1.25rem;
      font-weight: 800;
    }

    .required-note {
      display: inline-block;
      margin-top: 0.35rem;
      color: var(--muted);
      font-size: 0.95rem;
      font-weight: 500;
    }

    .choices {
      display: grid;
      gap: 0.875rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      min-width: 0;
      padding: 1rem;
      color: var(--text);
      background: #0f172a;
      border: 0.125rem solid var(--border);
      border-radius: 1rem;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      background: #172036;
      border-color: var(--accent);
      transform: translateY(-0.0625rem);
    }

    .choice input {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    .choice:has(input:checked) {
      color: var(--text);
      background: #12324b;
      border-color: var(--accent-strong);
    }

    .choice:has(input:focus-visible) {
      outline: 0.1875rem solid var(--focus);
      outline-offset: 0.1875rem;
    }

    .choice-text {
      min-width: 0;
      overflow-wrap: anywhere;
      font-weight: 700;
    }

    .submit-button {
      justify-self: start;
      min-width: 9rem;
      padding: 0.9rem 1.25rem;
      color: #03111d;
      background: linear-gradient(135deg, #bae6fd, var(--accent-strong));
      border: 0.125rem solid transparent;
      border-radius: 999px;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 0.75rem 1.75rem #07111f;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    .submit-button:hover {
      transform: translateY(-0.0625rem);
      box-shadow: 0 1rem 2rem #07111f;
    }

    .submit-button:focus-visible {
      outline: 0.1875rem solid var(--focus);
      outline-offset: 0.1875rem;
    }

    .status-message {
      min-height: 1.5rem;
      margin: 0;
      color: var(--accent);
      font-weight: 700;
    }

    @media (max-width: 22rem) {
      .page-shell {
        padding-inline: 0.75rem;
      }

      .card {
        border-radius: 1rem;
      }

      .choice {
        align-items: flex-start;
      }

      .submit-button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      body,
      .card,
      .choice,
      .submit-button,
      .skip-link {
        color: CanvasText;
        background: Canvas;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .eyebrow,
      .intro,
      .required-note,
      .status-message {
        color: CanvasText;
      }

      .choice:has(input:checked),
      .choice:hover {
        border-color: Highlight;
      }

      .submit-button {
        color: ButtonText;
        border-color: ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="root"></div>

  <script>
    const notificationOptions = [
      { id: "notification-email", value: "email", label: "Email" },
      { id: "notification-sms", value: "sms", label: "SMS" },
      { id: "notification-push", value: "push", label: "Push Notifications" }
    ];

    function RadioOption({ id, value, label, required }) {
      return `
        <label class="choice" for="${id}">
          <input
            type="radio"
            id="${id}"
            name="notificationPreference"
            value="${value}"
            aria-invalid="false"
            ${required ? "required" : ""}
          >
          <span class="choice-text">${label}</span>
        </label>
      `;
    }

    function NotificationForm() {
      const optionsMarkup = notificationOptions
        .map((option, index) => RadioOption({ ...option, required: index === 0 }))
        .join("");

      return `
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help form-status">
              <legend>
                How do you prefer to receive notifications?
                <span class="required-note" id="notification-help">Required. Choose one answer.</span>
              </legend>
              <div class="choices">
                ${optionsMarkup}
              </div>
            </fieldset>
          </div>
          <button class="submit-button" type="submit">Submit</button>
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

    function App() {
      return `
        <main class="page-shell" id="main-content">
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Preferences</p>
            <h1 id="page-title">Notification settings</h1>
            <p class="intro">
              Select the single channel that works best for timely updates and account reminders.
            </p>
            ${NotificationForm()}
          </section>
        </main>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const notificationForm = document.getElementById("notification-form");
    const notificationRadios = notificationForm.querySelectorAll("input[name='notificationPreference']");

    function setNotificationGroupInvalid(isInvalid) {
      notificationRadios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    }

    notificationForm.addEventListener("change", (event) => {
      if (event.target.matches("input[name='notificationPreference']")) {
        setNotificationGroupInvalid(false);
        document.getElementById("form-status").textContent = "";
      }
    });

    notificationForm.addEventListener("submit", (event) => {
      event.preventDefault();

      const form = event.currentTarget;
      const status = document.getElementById("form-status");
      const selected = form.elements.notificationPreference.value;

      if (!selected) {
        const firstRadio = notificationRadios[0];
        setNotificationGroupInvalid(true);
        status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
        firstRadio.focus();
        return;
      }

      setNotificationGroupInvalid(false);
      const selectedOption = notificationOptions.find((option) => option.value === selected);
      status.textContent = `Preference saved: ${selectedOption.label}.`;
    });
  </script>
</body>
</html>
